KG42.register("source_edge_archive-e364239efee6f3b600ec5280",{"id":"12-p2p_microgrid_trading::v141-c-R005::E::v141-c-R005-E001","paper":"12-p2p_microgrid_trading","rule_id":"v141-c-R005","rule_ref":"12-p2p_microgrid_trading::v141-c-R005","record":{"edge_id":"v141-c-R005-E001","source":"execution.energy_trade","target":"settlement.payment","type":"precedes","constraint_ids":["v141-c-R005-C001"],"evidence_ids":["v141-b-g01-ev-10"]},"evidence_class":"S","provenance_gate":"direct_C_edge_with_constraint_and_source_excerpt","scientific_acceptance":false,"accepted_constraint_ids":["v141-c-R005-C001"],"held_constraint_ids":[],"semantic_review_status":"supported","source":"COMP-45aa318377a72aa8","target":"COMP-739917e3869e45a6","source_occurrence_id":"12-p2p_microgrid_trading::v141-c-R005::V::execution.energy_trade","target_occurrence_id":"12-p2p_microgrid_trading::v141-c-R005::V::settlement.payment","source_unit_id":"12-p2p_microgrid_trading::v141-a-M01::execution.energy_trade","target_unit_id":"12-p2p_microgrid_trading::v141-a-M01::settlement.payment","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Settlement of differences between promised and actual P2P electricity generation or consumption. | The stated P2P energy-trading process sequence.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev-10","v141-b-g01-ev-11"]},"active":true,"source_signature":"99f5d88b2df750e0e2081601c6b9584d26769e44405aedd82d4f9bee7ba19750","relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"source_science":{"mechanism_id":"v141-a-M01","source_definition":"Peers buy or sell energy directly with each other without conventional energy suppliers acting as intermediaries. Scope: Direct P2P energy purchases and sales between peers. A prosumer with surplus electricity may sell it to other energy consumers. Scope: Sale of surplus electricity by prosumers to other energy consumers. Condition: The prosumer has surplus electricity. A Microgrid, a Cell or a region may be considered a peer and trade with other such peers. Scope: P2P architecture at Microgrid, Cell and region scales.","target_definition":"Energy exchange precedes the final settlement of bills and transactions through payment. Scope: The stated P2P energy-trading process sequence. The difference between promised and actual electricity generation or consumption must be calculated and charged during settlement. Scope: Settlement of differences between promised and actual P2P electricity generation or consumption. Condition: Promised and actual electricity generation or consumption quantities differ.","constraints":[{"constraint_id":"v141-c-R005-C001","kind":"procedural","role":"core","statement":"Energy exchange precedes the final settlement of bills and transactions through payment. Scope: The stated P2P energy-trading process sequence.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["execution.energy_trade","settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-ev-10"]}],"evidence":[{"evidence_id":"v141-b-g01-ev-10","location":{"location_id":"src-c1934be9b4-p03-c1r3__v141-a-M01-participation","page":3,"printed_page":null,"section":"2. Four-layer system architecture of Peer-to-Peer energy trading","anchor_text":"g , p coordinated way either connected to the main power network or is- ti landed. A Microgrid norma","equation_id":null,"figure_id":"Fig. 1","table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"The third dimension shows the time sequence of the P2P energy trading process. Bidding is the first process of P2P energy trading when energy customers (generators, consumers and prosumers) reach trading agreements with each other prior to the energy exchange. During the bidding process, energy customers interact with each other and agree on the price and amount of energy to be traded. Energy exchanging is the second process, during which energy is generated, transmitted and consumed. Settlement is the final process when bills and transactions are finally settled via settlement arrangements and payment."}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Settlement of differences between promised and actual P2P electricity generation or consumption. | The stated P2P energy-trading process sequence.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev-10","v141-b-g01-ev-11"]},"source_record":{"edge_id":"v141-c-R005-E001","source":"execution.energy_trade","target":"settlement.payment","type":"precedes","constraint_ids":["v141-c-R005-C001"],"evidence_ids":["v141-b-g01-ev-10"]},"paper_scope_note":"Buyer order placement and seller order placement are alternative processes; payment to the platform and the platform's distribution of bills are not the same data object; temporal order only preserves the source fact."}});
